import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import * as os from 'os';

interface FirmwareChunk {
  offset: number;
  data: Buffer;
  checksum: string;
}

interface RetryConfig {
  maxRetries: number;
  backoffMs: number;
  rateLimitPerSec: number;
}

class RateLimiter {
  private tokens: number;
  private lastRefill: number;
  private readonly maxTokens: number;
  private readonly refillRate: number;

  constructor(ratePerSec: number) {
    this.maxTokens = ratePerSec;
    this.tokens = ratePerSec;
    this.refillRate = ratePerSec;
    this.lastRefill = Date.now();
  }

  async acquire(): Promise<boolean> {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(this.maxTokens, this.tokens + elapsed * this.refillRate);
    this.lastRefill = now;
    if (this.tokens >= 1) {
      this.tokens -= 1;
      return true;
    }
    return false;
  }
}

class FirmwareUpdateManager {
  private readonly deviceId: string;
  private readonly retryConfig: RetryConfig;
  private readonly rateLimiter: RateLimiter;
  private readonly stagingDir: string;
  private updateInProgress: boolean = false;

  constructor(deviceId: string, config: RetryConfig) {
    this.deviceId = deviceId;
    this.retryConfig = config;
    this.rateLimiter = new RateLimiter(config.rateLimitPerSec);
    this.stagingDir = this.initStagingDirectory();
  }

  private initStagingDirectory(): string {
    const baseDir = path.join(os.tmpdir(), 'iot-firmware');
    if (!fs.existsSync(baseDir)) {
      fs.mkdirSync(baseDir, { recursive: true, mode: 0o700 });
    }
    return baseDir;
  }

  private generateSessionToken(): string {
    return crypto.randomBytes(16).toString('hex');
  }

  private computeIntegrity(data: Buffer): string {
    return crypto.createHash('sha256').update(data).digest('hex');
  }

  private createStagingFile(sessionToken: string, chunkIndex: number): string {
    const timestamp = Date.now();
    const filename = `fw_${this.deviceId}_${sessionToken}_${chunkIndex}_${timestamp}`;
    return path.join(this.stagingDir, filename);
  }

  private async writeChunkWithRetry(chunk: FirmwareChunk, filePath: string): Promise<boolean> {
    let attempts = 0;
    while (attempts < this.retryConfig.maxRetries) {
      const canProceed = await this.rateLimiter.acquire();
      if (!canProceed) {
        await this.delay(100);
        continue;
      }
      try {
        const integrity = this.computeIntegrity(chunk.data);
        if (integrity !== chunk.checksum) {
          throw new Error(`Integrity check failed for chunk at offset ${chunk.offset}`);
        }
        const fd = fs.openSync(filePath, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL, 0o600);
        try {
          fs.writeSync(fd, chunk.data);
        } finally {
          fs.closeSync(fd);
        }
        return true;
      } catch (err) {
        attempts++;
        if (attempts < this.retryConfig.maxRetries) {
          await this.delay(this.retryConfig.backoffMs * Math.pow(2, attempts));
        }
      }
    }
    return false;
  }

  async processUpdate(chunks: FirmwareChunk[]): Promise<{ success: boolean; outputPath: string | null }> {
    if (this.updateInProgress) {
      return { success: false, outputPath: null };
    }
    this.updateInProgress = true;
    const sessionToken = this.generateSessionToken();
    const chunkFiles: string[] = [];

    try {
      for (let i = 0; i < chunks.length; i++) {
        const stagingPath = this.createStagingFile(sessionToken, i);
        const written = await this.writeChunkWithRetry(chunks[i], stagingPath);
        if (!written) {
          this.cleanupFiles(chunkFiles);
          return { success: false, outputPath: null };
        }
        chunkFiles.push(stagingPath);
      }

      const finalPath = await this.assembleImage(chunkFiles, sessionToken);
      return { success: true, outputPath: finalPath };
    } finally {
      this.updateInProgress = false;
      this.cleanupFiles(chunkFiles);
    }
  }

  private async assembleImage(chunkFiles: string[], sessionToken: string): Promise<string> {
    const outputFilename = `firmware_${this.deviceId}_${sessionToken}.bin`;
    const outputPath = path.join(this.stagingDir, outputFilename);
    const fd = fs.openSync(outputPath, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL, 0o600);
    try {
      for (const chunkFile of chunkFiles) {
        const data = fs.readFileSync(chunkFile);
        fs.writeSync(fd, data);
      }
    } finally {
      fs.closeSync(fd);
    }
    return outputPath;
  }

  private cleanupFiles(files: string[]): void {
    for (const file of files) {
      try {
        if (fs.existsSync(file)) {
          fs.unlinkSync(file);
        }
      } catch { /* best effort cleanup */ }
    }
  }

  private delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

export { FirmwareUpdateManager, RetryConfig, FirmwareChunk };
